DROP PROCEDURE IF EXISTS `cursor_ROWPERROW`; 
CREATE PROCEDURE cursor_ROWPERROW() BEGIN 	DECLARE cursor_CALENDAR_ID INT; 	DECLARE cursor_DATE DATE; 	DECLARE cursor_STATUS ENUM('available','pending','booked'); 	DECLARE cursor_CHANGE_OVER INT; 	DECLARE next_DATE DATE; 	DECLARE next_STATUS ENUM('available','pending','booked'); 	DECLARE next_CHANGE_OVER INT; 	DECLARE based TEXT; 	DECLARE cnt INT DEFAULT 1; 	DECLARE currentSTATUS ENUM('available','pending','booked'); 	DECLARE currentCHANGE INT; 	DECLARE availableSTATUS ENUM('available','pending','booked'); 	DECLARE done INT DEFAULT FALSE; 	DECLARE cursor_i CURSOR FOR SELECT `calendar_id`,`date`,`status`,`is_change_over` FROM `ac_dates`; 	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE; 	OPEN cursor_i; 	SET cnt = 1; 	SET availableSTATUS = 'available'; 	read_loop: LOOP 		FETCH cursor_i INTO cursor_CALENDAR_ID,cursor_DATE,cursor_STATUS,cursor_CHANGE_OVER; 		IF done THEN 			LEAVE read_loop; 		END IF; 		SELECT `value` INTO based FROM `options` WHERE `key`='o_price_based_on' AND `foreign_id`=cursor_CALENDAR_ID; 		IF based='days|nights::nights' THEN 			IF cnt=1 THEN 				SET currentSTATUS=cursor_STATUS; 				SET currentCHANGE=cursor_CHANGE_OVER; 				IF cursor_CHANGE_OVER=1 THEN 					UPDATE `ac_dates` SET `status_morning`=availableSTATUS, `status_afternoon`=cursor_STATUS WHERE `calendar_id`=cursor_CALENDAR_ID AND `date`=cursor_DATE; 				ELSE 					UPDATE `ac_dates` SET `status_morning`=cursor_STATUS, `status_afternoon`=cursor_STATUS WHERE `calendar_id`=cursor_CALENDAR_ID AND `date`=cursor_DATE; 				END IF; 			ELSE 				IF cursor_CHANGE_OVER=1 THEN 					IF cursor_STATUS=currentSTATUS THEN 						SET next_DATE = DATE_ADD(cursor_DATE, INTERVAL 1 DAY); 			 						IF EXISTS (SELECT `status`,`is_change_over` FROM `ac_dates` WHERE `calendar_id`=cursor_CALENDAR_ID AND `date`=next_DATE) THEN 							SELECT `status`,`is_change_over` INTO next_STATUS, next_CHANGE_OVER FROM `ac_dates` WHERE `calendar_id`=cursor_CALENDAR_ID AND `date`=next_DATE; 							UPDATE `ac_dates` SET `status_morning`=currentSTATUS WHERE `calendar_id`=cursor_CALENDAR_ID AND `date`=cursor_DATE; 							SET currentSTATUS = next_STATUS; 							UPDATE `ac_dates` SET `status_afternoon`=currentSTATUS WHERE `calendar_id`=cursor_CALENDAR_ID AND `date`=cursor_DATE; 						ELSE 							UPDATE `ac_dates` SET `status_morning`=currentSTATUS WHERE `calendar_id`=cursor_CALENDAR_ID AND `date`=cursor_DATE; 							SET currentSTATUS = 'available'; 							UPDATE `ac_dates` SET `status_afternoon`=currentSTATUS WHERE `calendar_id`=cursor_CALENDAR_ID AND `date`=cursor_DATE; 						END IF; 					ELSE 						UPDATE `ac_dates` SET `status_morning`=currentSTATUS WHERE `calendar_id`=cursor_CALENDAR_ID AND `date`=cursor_DATE; 						SET currentSTATUS=cursor_STATUS; 						UPDATE `ac_dates` SET `status_afternoon`=currentSTATUS WHERE `calendar_id`=cursor_CALENDAR_ID AND `date`=cursor_DATE; 					END IF; 				ELSE 					UPDATE `ac_dates` SET `status_morning`=cursor_STATUS,`status_afternoon`=cursor_STATUS WHERE `calendar_id`=cursor_CALENDAR_ID AND `date`=cursor_DATE; 				END IF; 			END IF; 		ELSE 			UPDATE `ac_dates` SET `status_morning`=cursor_STATUS, `status_afternoon`=cursor_STATUS WHERE `calendar_id`=cursor_CALENDAR_ID AND `date`=cursor_DATE; 		END IF; 		SET cnt = cnt + 1; 	END LOOP; 	CLOSE cursor_i; END; 
call cursor_ROWPERROW();
